import{_ as s,o as i,c as a,ag as t}from"./chunks/framework.DC2M1AAK.js";const k=JSON.parse('{"title":"Deploying a Marg gateway","description":"","frontmatter":{},"headers":[],"relativePath":"run/deploy.md","filePath":"run/deploy.md"}'),o={name:"run/deploy.md"};function n(r,e,d,h,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="deploying-a-marg-gateway" tabindex="-1">Deploying a Marg gateway <a class="header-anchor" href="#deploying-a-marg-gateway" aria-label="Permalink to &quot;Deploying a Marg gateway&quot;">​</a></h1><p>One stateless Node process (no build step), behind TLS, with four optional profiles. The production checklist in <code>docs/PRODUCTION-CHECKLIST.md</code> is the gate; this file is the mechanics.</p><h2 id="with-docker-compose" tabindex="-1">With Docker Compose <a class="header-anchor" href="#with-docker-compose" aria-label="Permalink to &quot;With Docker Compose&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # fill it: model, identity, secrets, origins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stores</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> observability</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$AGENT_DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/health</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # chain state, stores, writes flag, version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> o2:bootstrap</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                # dashboards + alerts into OpenObserve (AGENT_O2_* from .env.production)</span></span></code></pre></div><p>Profiles: <code>stores</code> (Redis + Mongo — sessions, ledgers, shared counters), <code>observability</code> (OpenObserve), <code>decisions</code> (Ollama with <code>laya</code> for Verdict&#39;s System One backend), <code>edge</code> (Caddy with automatic TLS for <code>AGENT_DOMAIN</code>). Without <code>stores</code> the gateway keeps sessions in memory with a file fallback under the <code>gateway-data</code> volume — fine for one replica, not for two.</p><h2 id="the-hosted-playground" tabindex="-1">The hosted playground <a class="header-anchor" href="#the-hosted-playground" aria-label="Permalink to &quot;The hosted playground&quot;">​</a></h2><p><code>render.yaml</code> at the repository root is a Render Blueprint for the public playground: the same image on the free tier with <code>LLM_CHAIN=mock</code>, writes off, no login and the rate limits on. New → Blueprint on Render, point it at the repository, done. It sleeps when idle and keeps no disk, so sessions may be lost; it is a demo, not a deployment.</p><h2 id="without-docker" tabindex="-1">Without Docker <a class="header-anchor" href="#without-docker" aria-label="Permalink to &quot;Without Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # the gateway reads .env</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">production</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/gateway/src/server.ts</span></span></code></pre></div><p>Run it under systemd (<code>Restart=always</code>, <code>KillSignal=SIGTERM</code>, <code>TimeoutStopSec=40</code>) behind any reverse proxy that passes SSE through unbuffered (nginx: <code>proxy_buffering off; proxy_read_timeout 600s;</code>). Set <code>AGENT_TRUST_PROXY=true</code> so rate limits see the client IP.</p><h2 id="operating-it" tabindex="-1">Operating it <a class="header-anchor" href="#operating-it" aria-label="Permalink to &quot;Operating it&quot;">​</a></h2><ul><li><strong>Rolling update</strong> — <code>docker compose … up -d --build gateway</code>. SIGTERM drains in-flight turns for <code>AGENT_SHUTDOWN_GRACE_MS</code> (default 10 s); the compose <code>stop_grace_period</code> is 40 s.</li><li><strong>Scaling</strong> — with <code>stores</code> on, the gateway is stateless: run N replicas behind the edge; rate limits and caps are shared through Redis.</li><li><strong>Health</strong> — <code>GET /api/health</code>: model chain and breaker state, stores, writes flag, otel. Alert on it, and on the error-ratio alert that <code>o2:bootstrap</code> installs.</li><li><strong>Backups</strong> — the volumes <code>mongo-data</code>, <code>redis-data</code>, <code>gateway-data</code> (uploads and the file fallback), <code>o2-data</code>.</li><li><strong>Secrets</strong> — <code>.env.production</code> only; nothing in the image. Rotate <code>AGENT_TOKEN_SECRET</code> by restarting with a new value (agent tokens live <code>AGENT_TOKEN_TTL_S</code>, default 15 min).</li><li><strong>Logs</strong> — structured JSON on stdout (<code>docker logs</code>), shipped to OpenObserve when <code>AGENT_O2_URL</code> is set, with the trace id on every line.</li><li><strong>Kubernetes</strong> — the same image; readiness and liveness on <code>/api/health</code>; <code>terminationGracePeriodSeconds: 40</code>; env from a Secret.</li></ul><h2 id="before-the-first-real-user" tabindex="-1">Before the first real user <a class="header-anchor" href="#before-the-first-real-user" aria-label="Permalink to &quot;Before the first real user&quot;">​</a></h2><p>Run the checklist: <code>docs/PRODUCTION-CHECKLIST.md</code>. The short version — a real model chain (<code>LLM_CHAIN</code> ≠ mock), <code>AGENT_REQUIRE_LOGIN=true</code> with <code>AGENT_AUTH_VERIFY_URL</code>, <code>AGENT_TOKEN_SECRET</code>, <code>AGENT_ADMIN_KEY</code>, <code>AGENT_CORS_ORIGINS</code> set, the write probe run against the real backend, the eval suite green against the real chain, and every panel in OpenObserve showing data.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/deploy/DEPLOY.md">deploy/DEPLOY.md</a> — edit it there; the site mirrors the repository.</small></p>`,16)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
